const slack = $('Slack Trigger').first().json;

const files = Array.isArray(slack.files) ? slack.files : [];
const file = files.length > 0 ? files[0] : null;

return [
  {
    json: {
      source: 'slack',

      // Submission information
      submitter_id: slack.user ?? null,
      channel_id: slack.channel ?? null,
      message_ts: slack.ts ?? null,
      message_text: slack.text ?? '',
      submitted_at: slack.event_ts ?? null,

      // Receipt information
      receipt_file_present: !!file,
      receipt_file_count: files.length,

      receipt_id: file?.id ?? null,
      file_name: file?.name ?? null,
      file_title: file?.title ?? null,
      mime_type: file?.mimetype ?? null,
      file_type: file?.filetype ?? null,
      file_size: file?.size ?? null,

      // Slack's event payload contains url_private in your test.
      file_url: file?.url_private ?? null
    }
  }
];

const metadata = $('Extract Receipt Metadata').first().json;

// Get the actual binary bytes from n8n.
// This is important because binary.data may contain a filesystem-v2
// reference instead of the actual base64 content.
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');

if (!buffer || buffer.length === 0) {
  throw new Error('Receipt binary data is empty or could not be read.');
}

const mimeType = metadata.mime_type || 'image/png';
const base64 = buffer.toString('base64');

let openai_content;

if (mimeType === 'application/pdf') {
  openai_content = {
    type: 'input_file',
    filename: metadata.file_name || 'receipt.pdf',
    file_data: `data:${mimeType};base64,${base64}`
  };
} else {
  openai_content = {
    type: 'input_image',
    image_url: `data:${mimeType};base64,${base64}`,
    detail: 'high'
  };
}

return [
  {
    json: {
      ...metadata,
      openai_content
    }
  }
];

const response = $json;

let outputText = null;

if (Array.isArray(response.output)) {
  for (const outputItem of response.output) {
    if (!Array.isArray(outputItem.content)) continue;

    for (const contentItem of outputItem.content) {
      if (contentItem.type === 'output_text' && typeof contentItem.text === 'string') {
        outputText = contentItem.text;
        break;
      }
    }

    if (outputText) break;
  }
}

if (!outputText && typeof response.output_text === 'string') {
  outputText = response.output_text;
}

if (!outputText) {
  throw new Error('OpenAI returned no structured receipt extraction.');
}

let extraction;

try {
  extraction = JSON.parse(outputText);
} catch (error) {
  throw new Error(`Could not parse OpenAI receipt JSON: ${error.message}`);
}

const metadata = $('Extract Receipt Metadata').first().json;

return [
  {
    json: {
      ...metadata,
      extraction
    }
  }
];

const extraction = $json.extraction || {};

const problems = [];

if (extraction.receipt_valid !== true) {
  problems.push('Receipt could not be confidently identified as a valid receipt.');
}

if (!extraction.merchant || extraction.merchant.trim() === '') {
  problems.push('Merchant could not be extracted.');
}

if (!extraction.transaction_date || extraction.transaction_date.trim() === '') {
  problems.push('Transaction date could not be extracted.');
}

if (!extraction.currency || extraction.currency.trim() === '') {
  problems.push('Currency could not be extracted.');
}

if (typeof extraction.total !== 'number' || extraction.total <= 0) {
  problems.push('A valid total could not be extracted.');
}

if (typeof extraction.extraction_confidence !== 'number' || extraction.extraction_confidence < 0.75) {
  problems.push('Extraction confidence is below the required threshold.');
}

if (Array.isArray(extraction.unclear_fields) && extraction.unclear_fields.length > 0) {
  problems.push(`Unclear fields: ${extraction.unclear_fields.join(', ')}`);
}

const subtotal = Number(extraction.subtotal || 0);
const tax = Number(extraction.tax || 0);
const total = Number(extraction.total || 0);

if (subtotal > 0 && total > 0) {
  const difference = Math.abs((subtotal + tax) - total);

  if (difference > 0.05) {
    problems.push('Subtotal plus tax does not reconcile with the extracted total.');
  }
}

const lineItems = Array.isArray(extraction.line_items)
  ? extraction.line_items
  : [];

if (lineItems.length > 0 && subtotal > 0) {
  const lineItemTotal = lineItems.reduce(
    (sum, item) => sum + Number(item.amount || 0),
    0
  );

  if (Math.abs(lineItemTotal - subtotal) > 0.05) {
    problems.push('Line item amounts do not reconcile with the extracted subtotal.');
  }
}

const needsReview = problems.length > 0 || extraction.needs_review === true;

return [
  {
    json: {
      ...$json,
      extraction_quality_passed: !needsReview,
      needs_review: needsReview,
      validation_problems: problems
    }
  }
];

const metadata = {
  source: $json.source,
  submitter_id: $json.submitter_id,
  channel_id: $json.channel_id,
  message_ts: $json.message_ts,
  message_text: $json.message_text,
  submitted_at: $json.submitted_at,
  receipt_id: $json.receipt_id,
  file_name: $json.file_name,
  mime_type: $json.mime_type
};

const extraction = $json.extraction || {};

const currencyMap = {
  '£': 'GBP',
  'GBP': 'GBP',
  '$': 'USD',
  'USD': 'USD',
  '€': 'EUR',
  'EUR': 'EUR'
};

const currency = currencyMap[extraction.currency] || extraction.currency || 'UNKNOWN';

return [
  {
    json: {
      ...metadata,
      audit_payload: {
        expense_id: $json.receipt_id,
        source: 'slack',
        submitter_id: $json.submitter_id,
        channel_id: $json.channel_id,
        message_ts: $json.message_ts,
        message_text: $json.message_text,
        submitted_at: $json.submitted_at,

        receipt: {
          receipt_id: $json.receipt_id,
          file_name: $json.file_name,
          mime_type: $json.mime_type,
          merchant: extraction.merchant || '',
          transaction_date: extraction.transaction_date || '',
          currency,
          subtotal: Number(extraction.subtotal || 0),
          tax: Number(extraction.tax || 0),
          total: Number(extraction.total || 0),
          line_items: Array.isArray(extraction.line_items)
            ? extraction.line_items
            : []
        },

        extraction: {
          confidence: Number(extraction.extraction_confidence || 0),
          unclear_fields: Array.isArray(extraction.unclear_fields)
            ? extraction.unclear_fields
            : [],
          needs_review: extraction.needs_review === true
        }
      }
    }
  }
];

const payload = $json.audit_payload || {};
const receipt = payload.receipt || {};
const extraction = payload.extraction || {};

const total = Number(receipt.total || 0);

// -----------------------------
// Parse receipt transaction date
// -----------------------------
function parseTransactionDate(value) {
  if (!value || typeof value !== 'string') return null;

  // UK format: DD/MM/YYYY
  const uk = value.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);

  if (uk) {
    const day = Number(uk[1]);
    const month = Number(uk[2]) - 1;
    const year = Number(uk[3]);
    return new Date(Date.UTC(year, month, day, 12, 0, 0));
  }

  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? null : parsed;
}

// -----------------------------
// Add one calendar month
// -----------------------------
function addOneMonth(date) {
  const result = new Date(date.getTime());
  const originalDay = result.getUTCDate();

  result.setUTCMonth(result.getUTCMonth() + 1);

  // Handle dates such as 31 January -> 28 February
  if (result.getUTCDate() < originalDay) {
    result.setUTCDate(0);
  }

  return result;
}

const transactionDate = parseTransactionDate(receipt.transaction_date);

let submissionDate = null;

if (payload.submitted_at !== null && payload.submitted_at !== undefined) {
  const timestamp = Number(payload.submitted_at);

  if (Number.isFinite(timestamp)) {
    submissionDate = new Date(timestamp * 1000);
  }
}

const cutoffDate = transactionDate
  ? addOneMonth(transactionDate)
  : null;

const cutoffBreached = Boolean(
  transactionDate &&
  submissionDate &&
  submissionDate > cutoffDate
);

// -----------------------------
// Approval thresholds
// Current project rule: £2,000 CFO threshold
// Handbook baseline: >£250 requires advance line-manager approval
// -----------------------------
const cfoApprovalRequired = total >= 2000;
const lineManagerApprovalRequired = total > 250 && total < 2000;

const flags = [];
const approvals = [];

if (cutoffBreached) {
  flags.push('EXPENSE_OUTSIDE_ONE_MONTH_CUTOFF');
}

if (cfoApprovalRequired) {
  flags.push('CFO_APPROVAL_THRESHOLD');
  approvals.push('CFO_APPROVAL');
} else if (lineManagerApprovalRequired) {
  approvals.push('LINE_MANAGER_APPROVAL');
}

if (extraction.needs_review === true) {
  flags.push('EXTRACTION_REQUIRES_REVIEW');
}

if (Array.isArray(extraction.unclear_fields) && extraction.unclear_fields.length > 0) {
  flags.push('UNCLEAR_RECEIPT_FIELDS');
}

const receiptPresent = Boolean(payload.receipt?.receipt_id);

if (!receiptPresent) {
  flags.push('RECEIPT_MISSING');
}

const humanReviewRequired =
  cutoffBreached ||
  cfoApprovalRequired ||
  extraction.needs_review === true ||
  !receiptPresent;

return [
  {
    json: {
      ...$json,
      policy_checks: {
        one_month_cutoff: {
          transaction_date: transactionDate
            ? transactionDate.toISOString().slice(0, 10)
            : null,
          submission_date: submissionDate
            ? submissionDate.toISOString().slice(0, 10)
            : null,
          cutoff_date: cutoffDate
            ? cutoffDate.toISOString().slice(0, 10)
            : null,
          passed: transactionDate && submissionDate
            ? !cutoffBreached
            : null,
          breached: cutoffBreached
        },

        approval: {
          total,
          cfo_threshold: 2000,
          cfo_approval_required: cfoApprovalRequired,
          line_manager_threshold: 250,
          line_manager_approval_required: lineManagerApprovalRequired
        },

        receipt: {
          present: receiptPresent
        },

        flags,
        approvals_required: approvals,
        human_review_required: humanReviewRequired
      }
    }
  }
];

const payload = $json.audit_payload || {};
const policy = $json.policy_checks || {};

return [
  {
    json: {
      ...$json,
      audit_engine_input: {
        expense_id: payload.expense_id,
        submitted_by: payload.submitter_id,
        source: payload.source,
        receipt: payload.receipt,
        extraction: payload.extraction,
        policy_checks: policy,
        audit_context: {
          preliminary_status: policy.human_review_required
            ? 'NEEDS_REVIEW'
            : 'READY_FOR_AUDIT',
          deterministic_flags: policy.flags || [],
          approvals_required: policy.approvals_required || [],
          human_review_required: policy.human_review_required === true
        }
      }
    }
  }
];

const input = $json.audit_engine_input || {};
const receipt = input.receipt || {};
const policy = input.policy_checks || {};
const context = input.audit_context || {};

return [
  {
    json: {
      ...$json,
      audit_reasoning_input: {
        expense_id: input.expense_id,
        submitted_by: input.submitted_by,
        employee_message: input.receipt?.message_text || $json.message_text || '',
        merchant: receipt.merchant || '',
        transaction_date: receipt.transaction_date || '',
        currency: receipt.currency || '',
        subtotal: Number(receipt.subtotal || 0),
        tax: Number(receipt.tax || 0),
        total: Number(receipt.total || 0),
        line_items: Array.isArray(receipt.line_items)
          ? receipt.line_items
          : [],
        deterministic_flags: context.deterministic_flags || policy.flags || [],
        approvals_required: context.approvals_required || policy.approvals_required || [],
        human_review_required: context.human_review_required === true || policy.human_review_required === true
      }
    }
  }
];

