const body = $json.body || $json;

let payload = body.payload || body;

if (typeof payload === 'string') {
  try {
    payload = JSON.parse(payload);
  } catch (error) {
    throw new Error(`Could not parse Slack payload: ${error.message}`);
  }
}

if (payload.type !== 'view_submission') {
  throw new Error(`Unexpected Slack interaction type: ${payload.type || 'unknown'}`);
}

if (payload.view?.callback_id !== 'expense_submission') {
  throw new Error('Unexpected modal callback_id.');
}

const values = payload.view?.state?.values || {};

const category =
  values.expense_category_block?.expense_category?.selected_option?.value || '';

const categoryLabel =
  values.expense_category_block?.expense_category?.selected_option?.text?.text || '';

const otherCategory =
  values.other_category_block?.other_category?.value || '';

const businessPurpose =
  values.business_purpose_block?.business_purpose?.value || '';

const currency =
  values.currency_block?.currency?.selected_option?.value || 'AUTO';

const currencyLabel =
  values.currency_block?.currency?.selected_option?.text?.text || 'Let the system determine';

const receiptInput =
  values.receipt_block?.receipt_file || {};

let receiptFiles = [];

if (Array.isArray(receiptInput.files)) {
  receiptFiles = receiptInput.files;
} else if (Array.isArray(receiptInput.selected_files)) {
  receiptFiles = receiptInput.selected_files;
} else if (Array.isArray(receiptInput.selectedFiles)) {
  receiptFiles = receiptInput.selectedFiles;
}

const firstReceipt = receiptFiles[0] || null;

let privateMetadata = {};

if (payload.view?.private_metadata) {
  try {
    privateMetadata = JSON.parse(payload.view.private_metadata);
  } catch (_) {
    privateMetadata = {};
  }
}

const effectiveCategory =
  category === 'OTHER' && otherCategory.trim()
    ? otherCategory.trim()
    : category;

return [
  {
    json: {
      submission_type: payload.type,
      callback_id: payload.view.callback_id,
      view_id: payload.view.id || '',
      submitted_at: new Date().toISOString(),

      submitter_id: payload.user?.id || privateMetadata.user_id || '',
      team_id: payload.team?.id || privateMetadata.team_id || '',
      channel_id: privateMetadata.channel_id || '',

      category,
      category_label: categoryLabel,
      other_category: otherCategory,
      effective_category: effectiveCategory,

      business_purpose: businessPurpose,

      currency,
      currency_label: currencyLabel,
      currency_needs_determination: currency === 'AUTO',

      receipt_file_id:
        firstReceipt?.id || firstReceipt?.file_id || '',
      receipt_file_name:
        firstReceipt?.name || firstReceipt?.title || '',
      receipt_mime_type:
        firstReceipt?.mimetype || firstReceipt?.mime_type || '',
      receipt_file_url:
        firstReceipt?.url_private_download ||
        firstReceipt?.url_private ||
        '',
      receipt_file: firstReceipt,

      raw_slack_payload: payload
    }
  }
];

const item = $json;

// The category is mandatory because the handbook requires
// every expense to be coded at the point of submission.
if (!item.category) {
  throw new Error('No expense category was submitted.');
}

// A receipt is mandatory for this workflow.
if (!item.receipt_file_id && !item.receipt_file_url) {
  throw new Error('No receipt file was submitted.');
}

return [
  {
    json: {
      ...item,

      expense_submission: {
        expense_id:
          item.receipt_file_id ||
          `expense-${Date.now()}`,

        submitter_id:
          item.submitter_id || '',

        team_id:
          item.team_id || '',

        channel_id:
          item.channel_id || '',

        category:
          item.category,

        category_label:
          item.category_label || '',

        currency:
          item.currency || 'AUTO',

        currency_label:
          item.currency_label ||
          'Let the system determine',

        currency_needs_determination:
          item.currency === 'AUTO',

        receipt: {
          file_id:
            item.receipt_file_id || '',

          file_name:
            item.receipt_file_name || '',

          mime_type:
            item.receipt_mime_type || '',

          file_url:
            item.receipt_file_url || ''
        }
      }
    }
  }
];

const response = $json;
const submission = $('Normalise Expense Submission').first().json;

if (response.ok === false) {
  throw new Error(`Slack files.info failed: ${response.error || 'unknown error'}`);
}

const file = response.file || {};

const fileUrl =
  file.url_private_download ||
  file.url_private ||
  submission.receipt_file_url ||
  '';

if (!fileUrl) {
  throw new Error('Slack did not return a private file URL.');
}

return [
  {
    json: {
      ...submission,
