const submission = $('Normalise Expense Submission').first().json;

// Get the actual receipt bytes from Download Modal Receipt.
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');

if (!buffer || buffer.length === 0) {
  throw new Error('Receipt binary data is empty or could not be read.');
}

const base64 = buffer.toString('base64');

const mimeType =
  submission.receipt_mime_type ||
  'image/png';

const fileName =
  submission.receipt_file_name ||
  'receipt';

const userCurrency =
  submission.currency ||
  'AUTO';

let openai_content;

if (mimeType === 'application/pdf') {
  openai_content = {
    type: 'input_file',
    filename: fileName,
    file_data: `data:${mimeType};base64,${base64}`
  };
} else {
  openai_content = {
    type: 'input_image',
    image_url: `data:${mimeType};base64,${base64}`,
    detail: 'high'
  };
}

return [
  {
    json: {
      ...submission,

      openai_content,

      submission_context: {
        category: submission.category || '',
        category_label: submission.category_label || '',
        currency: userCurrency,
        currency_was_supplied_by_employee:
          userCurrency !== 'AUTO'
      }
    }
  }
];

const response = $json;

let outputText = null;

if (Array.isArray(response.output)) {
  for (const outputItem of response.output) {

    if (!Array.isArray(outputItem.content)) {
      continue;
    }

    for (const contentItem of outputItem.content) {

      if (
        contentItem.type === 'output_text' &&
        typeof contentItem.text === 'string'
      ) {
        outputText = contentItem.text;
        break;
      }
    }

    if (outputText) {
      break;
    }
  }
}

if (
  !outputText &&
  typeof response.output_text === 'string'
) {
  outputText = response.output_text;
}

if (!outputText) {
  throw new Error(
    'OpenAI returned no receipt extraction result.'
  );
}

let extraction;

try {
  extraction = JSON.parse(outputText);
} catch (error) {
  throw new Error(
    `Could not parse receipt extraction JSON: ${error.message}`
  );
}

const submission =
  $('Normalise Expense Submission').first().json;

return [
  {
    json: {
      ...submission,

      extraction
    }
  }
];

const extraction = $json.extraction || {};

const problems = [];

if (extraction.receipt_valid !== true) {
  problems.push(
    'Receipt could not be confidently identified as a valid receipt.'
  );
}

if (
  !extraction.merchant ||
  extraction.merchant.trim() === ''
) {
  problems.push(
    'Merchant could not be extracted.'
  );
}

if (
  !extraction.transaction_date ||
  extraction.transaction_date.trim() === ''
) {
  problems.push(
    'Transaction date could not be extracted.'
  );
}

if (
  typeof extraction.total !== 'number' ||
  extraction.total <= 0
) {
  problems.push(
    'A valid total could not be extracted.'
  );
}

if (
  typeof extraction.extraction_confidence !== 'number' ||
  extraction.extraction_confidence < 0.75
) {
  problems.push(
    'Extraction confidence is below the required threshold.'
  );
}

if (
  Array.isArray(extraction.unclear_fields) &&
  extraction.unclear_fields.length > 0
) {
  problems.push(
    `Unclear fields: ${extraction.unclear_fields.join(', ')}`
  );
}

if (
  extraction.currency_status === 'NEEDS_REVIEW'
) {
  problems.push(
    'Currency could not be determined reliably.'
  );
}

const subtotal = Number(
  extraction.subtotal || 0
);

const tax = Number(
  extraction.tax || 0
);

const total = Number(
  extraction.total || 0
);

if (subtotal > 0 && total > 0) {

  const difference = Math.abs(
    (subtotal + tax) - total
  );

  if (difference > 0.05) {
    problems.push(
      'Subtotal plus tax does not reconcile with total.'
    );
  }
}

const lineItems =
  Array.isArray(extraction.line_items)
    ? extraction.line_items
    : [];

if (
  lineItems.length > 0 &&
  subtotal > 0
) {

  const lineItemTotal =
    lineItems.reduce(
      (sum, item) =>
        sum + Number(item.amount || 0),
      0
    );

  if (
    Math.abs(
      lineItemTotal - subtotal
    ) > 0.05
  ) {
    problems.push(
      'Line item amounts do not reconcile with subtotal.'
    );
  }
}

const needsReview =
  problems.length > 0 ||
  extraction.needs_review === true;

return [
  {
    json: {
      ...$json,

      extraction_quality_passed:
        !needsReview,

      needs_review:
        needsReview,

      validation_problems:
        problems
    }
  }
];

