const extraction = $json.extraction || {};

const submission =
  $('Normalise Expense Submission').first().json;

const category =
  submission.category || '';

const categoryLabel =
  submission.category_label || '';

const submittedCurrency =
  submission.currency || 'AUTO';

let finalCurrency =
  extraction.currency || '';

if (
  submittedCurrency !== 'AUTO'
) {
  finalCurrency = submittedCurrency;
}

return [
  {
    json: {
      ...$json,

      audit_payload: {

        expense_id:
          submission.receipt_file_id ||
          `expense-${Date.now()}`,

        source:
          'slack_modal',

        submitter_id:
          submission.submitter_id || '',

        channel_id:
          submission.channel_id || '',

        submitted_at:
          submission.submitted_at || '',

        submission: {
          category,
          category_label: categoryLabel,

          currency_selected:
            submittedCurrency
        },

        receipt: {
          receipt_id:
            submission.receipt_file_id || '',

          file_name:
            submission.receipt_file_name || '',

          mime_type:
            submission.receipt_mime_type || '',

          merchant:
            extraction.merchant || '',

          transaction_date:
            extraction.transaction_date || '',

          currency:
            finalCurrency,

          currency_status:
            extraction.currency_status || '',

          subtotal:
            Number(extraction.subtotal || 0),

          tax:
            Number(extraction.tax || 0),

          total:
            Number(extraction.total || 0),

          line_items:
            Array.isArray(extraction.line_items)
              ? extraction.line_items
              : []
        },

        extraction: {

          confidence:
            Number(
              extraction.extraction_confidence || 0
            ),

          unclear_fields:
            Array.isArray(
              extraction.unclear_fields
            )
              ? extraction.unclear_fields
              : [],

          needs_review:
            extraction.needs_review === true
        }
      }
    }
  }
];

const payload =
  $json.audit_payload || {};

const receipt =
  payload.receipt || {};

const extraction =
  payload.extraction || {};

const total =
  Number(receipt.total || 0);

const flags = [];

const approvals = [];


// -----------------------------
// Parse transaction date
// -----------------------------

function parseTransactionDate(value) {

  if (
    !value ||
    typeof value !== 'string'
  ) {
    return null;
  }

  const uk =
    value.match(
      /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/
    );

  if (uk) {

    const day =
      Number(uk[1]);

    const month =
      Number(uk[2]) - 1;

    const year =
      Number(uk[3]);

    return new Date(
      Date.UTC(
        year,
        month,
        day,
        12,
        0,
        0
      )
    );
  }

  const parsed =
    new Date(value);

  return Number.isNaN(
    parsed.getTime()
  )
    ? null
    : parsed;
}


// -----------------------------
// Add one month
// -----------------------------

function addOneMonth(date) {

  const result =
    new Date(date.getTime());

  const originalDay =
    result.getUTCDate();

  result.setUTCMonth(
    result.getUTCMonth() + 1
  );

  if (
    result.getUTCDate() <
    originalDay
  ) {
    result.setUTCDate(0);
  }

  return result;
}


const transactionDate =
  parseTransactionDate(
    receipt.transaction_date
  );


let submissionDate =
  null;

if (
  payload.submitted_at
) {

  const parsed =
    new Date(
      payload.submitted_at
    );

  if (
    !Number.isNaN(
      parsed.getTime()
    )
  ) {
    submissionDate = parsed;
  }
}


const cutoffDate =
  transactionDate
    ? addOneMonth(
        transactionDate
      )
    : null;


const cutoffBreached =
  Boolean(
    transactionDate &&
    submissionDate &&
    submissionDate >
      cutoffDate
  );


// -----------------------------
// Currency
// -----------------------------

const currencyNeedsReview =
  receipt.currency_status ===
  'NEEDS_REVIEW';

if (currencyNeedsReview) {

  flags.push(
    'CURRENCY_REQUIRES_REVIEW'
  );
}


// -----------------------------
// Submission deadline
// -----------------------------

if (cutoffBreached) {

  flags.push(
    'EXPENSE_OUTSIDE_ONE_MONTH_CUTOFF'
  );
}


// -----------------------------
// Approval thresholds
// -----------------------------

const cfoApprovalRequired =
  receipt.currency === 'GBP' &&
  total >= 2000;


const lineManagerApprovalRequired =
  receipt.currency === 'GBP' &&
  total > 250 &&
  total < 2000;


if (cfoApprovalRequired) {

  flags.push(
    'CFO_APPROVAL_THRESHOLD'
  );

  approvals.push(
    'CFO_APPROVAL'
  );

} else if (
  lineManagerApprovalRequired
) {

  approvals.push(
    'LINE_MANAGER_APPROVAL'
  );
}


// -----------------------------
// Extraction
// -----------------------------

if (
  extraction.needs_review === true
) {

  flags.push(
    'EXTRACTION_REQUIRES_REVIEW'
  );
}


if (
  Array.isArray(
    extraction.unclear_fields
  ) &&
  extraction.unclear_fields.length > 0
) {

  flags.push(
    'UNCLEAR_RECEIPT_FIELDS'
  );
}


// -----------------------------
// Human review
// -----------------------------

const humanReviewRequired =
  cutoffBreached ||
  currencyNeedsReview ||
  extraction.needs_review === true ||
  cfoApprovalRequired;


return [
  {
    json: {

      ...$json,

      policy_checks: {

        one_month_cutoff: {

          transaction_date:
            transactionDate
              ? transactionDate
                  .toISOString()
                  .slice(0, 10)
              : null,

          submission_date:
            submissionDate
              ? submissionDate
                  .toISOString()
                  .slice(0, 10)
              : null,

          cutoff_date:
            cutoffDate
              ? cutoffDate
                  .toISOString()
                  .slice(0, 10)
              : null,

          passed:
            transactionDate &&
            submissionDate
              ? !cutoffBreached
              : null,

          breached:
            cutoffBreached
        },

        approval: {

          total,

          currency:
            receipt.currency,

          cfo_threshold:
            2000,

          cfo_approval_required:
            cfoApprovalRequired,

          line_manager_threshold:
            250,

          line_manager_approval_required:
            lineManagerApprovalRequired
        },

        currency: {

          currency:
            receipt.currency,

          status:
            receipt.currency_status,

          needs_review:
            currencyNeedsReview
        },

        category: {

          selected_category:
            payload.submission?.category || '',

          selected_category_label:
            payload.submission?.category_label || ''
        },

        flags,

        approvals_required:
          approvals,

        human_review_required:
          humanReviewRequired
      }
    }
  }
];

const payload =
  $json.audit_payload || {};

const policy =
  $json.policy_checks || {};

return [
  {
    json: {

      ...$json,

      audit_engine_input: {

        expense_id:
          payload.expense_id,

        submitted_by:
          payload.submitter_id,

        source:
          payload.source,

        submission:
          payload.submission || {},

        receipt:
          payload.receipt || {},

        extraction:
          payload.extraction || {},

        policy_checks:
          policy,

        audit_context: {

          preliminary_status:
            policy.human_review_required
              ? 'NEEDS_REVIEW'
              : 'READY_FOR_AUDIT',

          deterministic_flags:
            policy.flags || [],

          approvals_required:
            policy.approvals_required || [],

          human_review_required:
            policy.human_review_required === true
        }
      }
    }
  }
];

const input =
  $json.audit_engine_input || {};

const receipt =
  input.receipt || {};

const submission =
  input.submission || {};

const policy =
  input.policy_checks || {};

return [
  {
    json: {

      ...$json,

      audit_reasoning_input: {

        expense_id:
          input.expense_id,

        submitted_by:
          input.submitted_by,

        category:
          submission.category_label ||
          submission.category ||
          '',

        merchant:
          receipt.merchant || '',

        transaction_date:
          receipt.transaction_date || '',

        currency:
          receipt.currency || '',

        currency_status:
          receipt.currency_status || '',

        subtotal:
          Number(
            receipt.subtotal || 0
          ),

        tax:
          Number(
            receipt.tax || 0
          ),

        total:
          Number(
            receipt.total || 0
          ),

        line_items:
          Array.isArray(
            receipt.line_items
          )
            ? receipt.line_items
            : [],

        deterministic_flags:
          policy.flags || [],

        approvals_required:
          policy.approvals_required ||
          [],

        human_review_required:
          policy.human_review_required === true
      }
    }
  }
];

