const response = $json;

let outputText = null;

if (
  Array.isArray(response.output)
) {

  for (
    const outputItem of
    response.output
  ) {

    if (
      !Array.isArray(
        outputItem.content
      )
    ) {
      continue;
    }

    for (
      const contentItem of
      outputItem.content
    ) {

      if (
        contentItem.type ===
          'output_text' &&
        typeof contentItem.text ===
          'string'
      ) {

        outputText =
          contentItem.text;

        break;
      }
    }

    if (outputText) {
      break;
    }
  }
}

if (
  !outputText &&
  typeof response.output_text ===
    'string'
) {
  outputText =
    response.output_text;
}

if (!outputText) {
  throw new Error(
    'OpenAI returned no contextual audit result.'
  );
}

let audit;

try {

  audit =
    JSON.parse(
      outputText
    );

} catch (error) {

  throw new Error(
    `Could not parse contextual audit JSON: ${error.message}`
  );
}

return [
  {
    json: {

      ...$json,

      contextual_audit:
        audit
    }
  }
];

const policy =
  $json.policy_checks || {};

const audit =
  $json.contextual_audit || {};

const deterministicFlags =
  Array.isArray(policy.flags)
    ? policy.flags
    : [];

const contextualFlags =
  Array.isArray(
    audit.risk_factors
  )
    ? audit.risk_factors
    : [];

const combinedFlags = [
  ...new Set([
    ...deterministicFlags,
    ...contextualFlags
  ])
];

let riskLevel = 'LOW';

let reviewRequired = false;

let employeeExplanationRequired =
  false;


// HIGH
if (

  policy.human_review_required ===
    true ||

  audit.recommended_action ===
    'NEEDS_HUMAN_REVIEW' ||

  audit.business_relevance ===
    'LIKELY_PERSONAL' ||

  audit.reasonableness ===
    'UNREASONABLE'

) {

  riskLevel = 'HIGH';

  reviewRequired = true;

}


// MEDIUM
else if (

  audit.recommended_action ===
    'NEEDS_EMPLOYEE_EXPLANATION' ||

  audit.business_relevance ===
    'UNCLEAR' ||

  audit.reasonableness ===
    'QUESTIONABLE' ||

  audit.reasonableness ===
    'INSUFFICIENT_INFORMATION' ||

  Number(
    audit.confidence || 0
  ) < 0.75

) {

  riskLevel = 'MEDIUM';

  employeeExplanationRequired =
    true;

}


const status =

  riskLevel === 'HIGH'

    ? 'NEEDS_HUMAN_REVIEW'

    : riskLevel === 'MEDIUM'

      ? 'NEEDS_EMPLOYEE_EXPLANATION'

      : 'LOW_RISK';


return [
  {
    json: {

      ...$json,

      final_audit_result: {

        risk_level:
          riskLevel,

        status,

        review_required:
          reviewRequired,

        employee_explanation_required:
          employeeExplanationRequired,

        deterministic_flags:
          deterministicFlags,

        contextual_flags:
          contextualFlags,

        combined_flags:
          combinedFlags,

        contextual_summary:
          audit.summary || '',

        confidence:
          Number(
            audit.confidence || 0
          ),

        category_consistent:
          audit.category_consistent ??
          true,

        business_relevance:
          audit.business_relevance ||
          '',

        reasonableness:
          audit.reasonableness ||
          '',

        recommended_action:
          audit.recommended_action ||
          ''
      }
    }
  }
];

